options.getOption:
// Access the data frame safely using aliases 'x', 'y', and 'z'
const dataFrame = context.panel.data.series.find(s => s.fields && s.fields.length >= 3);

// Helper function to safely get the LATEST value by name
const getValueByName = (frame, name) => {
  const field = frame.fields.find(f => f.name === name);
  if (field && field.values.length > 0) {
    const lastIndex = field.values.length - 1;
    return field.values.get(lastIndex);
  }
  return 0; // Default to 0 if a field is missing or has no values
};

if (dataFrame) {
  // Get the current single values for x, y, and z
  const x = getValueByName(dataFrame, 'ax');
  const y = getValueByName(dataFrame, 'ay');
  const z = getValueByName(dataFrame, 'az');

  // Return the ECharts configuration to draw the vector
  return {
    grid3D: {
      boxWidth: 150,
      boxHeight: 150,
      boxDepth: 150,
      viewControl: {
        // Lock the camera perspective on refresh
        projection: 'perspective',
        autoRotate: false,
        alpha: 45,              // Set the vertical angle (adjust as needed)
        beta: 45,               // Set the horizontal angle (adjust as needed)
        distance: 250,          // Set the zoom level
      }
    },
    xAxis3D: { name: 'X Axis', min: -1000, max: 1000 },
    yAxis3D: { name: 'Y Axis', min: -1000, max: 1000 },
    zAxis3D: { name: 'Z Axis', min: -1000, max: 1000 },
    series: [
      {
        type: 'line3D',
        data: [[0, 0, 0], [x, y, z]], // Explicitly starts from origin
        lineStyle: { width: 2, color: '#ff0000' }
      },
      {
        type: 'scatter3D',
        symbol: 'arrow',
        symbolSize: 20,
        data: [[x, y, z]],
        itemStyle: { color: '#ff0000' }
      }
    ]
  };
}

// Return an empty object if data isn't ready yet
return {};

